 static long Triangles(Mesh m)=>Enumerable.Range(0,m.subMeshCount).Sum(i=>(long)m.GetIndexCount(i)/3);
 static Vector2[] UV(Mesh m,int channel){using(var data=MeshUtility.AcquireReadOnlyMeshData(m)){if(!data[0].HasVertexAttribute(channel==0?VertexAttribute.TexCoord0:VertexAttribute.TexCoord1))return new Vector2[0];using(var array=new NativeArray<Vector2>(m.vertexCount,Allocator.Temp)){data[0].GetUVs(channel,array);return array.ToArray();}}}
 static int[] Indices(Mesh m){var all=new List<int>();using(var data=MeshUtility.AcquireReadOnlyMeshData(m)){for(int s=0;s<m.subMeshCount;s++){using(var a=new NativeArray<int>((int)m.GetIndexCount(s),Allocator.Temp)){data[0].GetIndices(a,s);all.AddRange(a.ToArray());}}}return all.ToArray();}
 static float Overlap(Mesh m,int channel){var uv=UV(m,channel);if(uv.Length==0)return -1;var ids=Indices(m);const int size=128;var occupied=new byte[size*size];int overlap=0,total=0;for(int i=0;i<ids.Length;i+=3){var a=uv[ids[i]]*size;var b=uv[ids[i+1]]*size;var c=uv[ids[i+2]]*size;float den=(b.y-c.y)*(a.x-c.x)+(c.x-b.x)*(a.y-c.y);if(Mathf.Abs(den)<.0001f)continue;int minX=Mathf.Clamp(Mathf.FloorToInt(Mathf.Min(a.x,b.x,c.x)),0,size-1),maxX=Mathf.Clamp(Mathf.CeilToInt(Mathf.Max(a.x,b.x,c.x)),0,size-1),minY=Mathf.Clamp(Mathf.FloorToInt(Mathf.Min(a.y,b.y,c.y)),0,size-1),maxY=Mathf.Clamp(Mathf.CeilToInt(Mathf.Max(a.y,b.y,c.y)),0,size-1);for(int y=minY;y<=maxY;y++)for(int x=minX;x<=maxX;x++){float px=x+.5f,py=y+.5f;float u=((b.y-c.y)*(px-c.x)+(c.x-b.x)*(py-c.y))/den,v=((c.y-a.y)*(px-c.x)+(a.x-c.x)*(py-c.y))/den;if(u<=.00001f||v<=.00001f||u+v>=.99999f)continue;int k=y*size+x;if(occupied[k]==0){occupied[k]=1;total++;}else if(occupied[k]==1){occupied[k]=2;overlap++;}}}return total>0?(float)overlap/total:0;}
 static void AuditSource(Cmd c){Open(Source(c.quality,c.composer));var r=Arena();var meshes=r.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh).Select(f=>f.sharedMesh).Distinct().ToArray();var rows=meshes.Select(m=>new MeshRow{path=AssetDatabase.GetAssetPath(m),name=m.name,vertices=m.vertexCount,triangles=(int)Triangles(m),uv0=m.HasVertexAttribute(VertexAttribute.TexCoord0),uv2=m.HasVertexAttribute(VertexAttribute.TexCoord1),bytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(m),uv0Overlap=Overlap(m,0),uv2Overlap=m.HasVertexAttribute(VertexAttribute.TexCoord1)?Overlap(m,1):-1}).ToArray();var textures=r.GetComponentsInChildren<Renderer>(true).SelectMany(x=>x.sharedMaterials).Where(m=>m).SelectMany(m=>m.GetTexturePropertyNames().Select(m.GetTexture)).OfType<Texture2D>().Distinct().Select(t=>AssetDatabase.GetAssetPath(t)+"|"+t.width+"x"+t.height+"|mips="+t.mipmapCount+"|aniso="+t.anisoLevel+"|filter="+t.filterMode).ToArray();var lights=r.GetComponentsInChildren<Light>(true);var audit=new Audit{gpu=SystemInfo.graphicsDeviceName,graphicsApi=SystemInfo.graphicsDeviceType.ToString(),renderers=r.GetComponentsInChildren<Renderer>(true).Length,lights=lights.Length,realtimeLights=lights.Count(l=>l.enabled&&l.lightmapBakeType!=LightmapBakeType.Baked),probes=r.GetComponentsInChildren<ReflectionProbe>(true).Length,triangles=r.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh).Sum(f=>Triangles(f.sharedMesh)),meshes=rows,textures=textures};File.WriteAllText(Output+"/audit_"+c.quality+".json",JsonUtility.ToJson(audit,true));}
 static void Prepare(Cmd c){Open(Source(c.quality,c.composer));var root=Arena();var mats=new Dictionary<Material,Material>();string dir=Lab+"/Materials/"+c.caseName;Directory.CreateDirectory(dir);AssetDatabase.Refresh();
  foreach(var renderer in root.GetComponentsInChildren<Renderer>(true)){var materials=renderer.sharedMaterials;for(int i=0;i<materials.Length;i++){var source=materials[i];if(!source)continue;if(!mats.TryGetValue(source,out var copy)){string key=AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(source));string path=dir+"/"+key+".mat";copy=AssetDatabase.LoadAssetAtPath<Material>(path);if(!copy){copy=new Material(source);AssetDatabase.CreateAsset(copy,path);}else copy.CopyPropertiesFromMaterial(source);if(renderer.name=="Floor"&&c.composer=="Monteverdi")copy.shader=Shader.Find("MusicGame/Art/MonteverdiPilotFloor");if(c.stable){if(copy.HasProperty("_SpecularAA"))copy.SetFloat("_SpecularAA",1);if(copy.HasProperty("_Smoothness"))copy.SetFloat("_Smoothness",Mathf.Min(copy.GetFloat("_Smoothness"),renderer.name=="Floor"?.52f:.48f));if(copy.HasProperty("_BumpScale"))copy.SetFloat("_BumpScale",Mathf.Min(copy.GetFloat("_BumpScale"),.4f));}EditorUtility.SetDirty(copy);mats[source]=copy;}materials[i]=copy;}renderer.sharedMaterials=materials;}
  if(c.lighting!="realtime"){
   foreach(var renderer in root.GetComponentsInChildren<MeshRenderer>(true)){bool foliage=renderer.sharedMaterials.Any(m=>m&&m.shader.name.Contains("GardenFoliage"));GameObjectUtility.SetStaticEditorFlags(renderer.gameObject,foliage?0:StaticEditorFlags.ContributeGI);renderer.receiveGI=ReceiveGI.LightProbes;renderer.lightProbeUsage=LightProbeUsage.BlendProbes;
    if(c.lighting=="hybrid"&&renderer.name=="Floor"){var filter=renderer.GetComponent<MeshFilter>();var source=filter.sharedMesh;string meshPath=Lab+"/FloorLightmapUV.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(!mesh){mesh=Object.Instantiate(source);mesh.name="MonteverdiFloor_SharedUV0andUV1";if(Overlap(source,0)>.001f)throw new Exception("Floor UV0 overlap; cannot reuse blindly");mesh.uv2=UV(source,0);AssetDatabase.CreateAsset(mesh,meshPath);}filter.sharedMesh=mesh;renderer.receiveGI=ReceiveGI.Lightmaps;renderer.scaleInLightmap=1;}
    else if(c.optimize&&c.lighting=="hybrid"){var f=renderer.GetComponent<MeshFilter>();if(f&&f.sharedMesh&&f.sharedMesh.name=="Cube"&&f.sharedMesh.HasVertexAttribute(VertexAttribute.TexCoord1))renderer.receiveGI=ReceiveGI.Lightmaps;}
   }
   var probes=new GameObject("Pilot_LightProbes").AddComponent<LightProbeGroup>();probes.transform.SetParent(root.transform,false);var positions=new List<Vector3>();foreach(float x in new[]{-7.5f,-5,-2.5f,0,2.5f,5,7.5f})foreach(float z in new[]{-7f,-3.5f,0,3.5f,7,10.5f})foreach(float y in new[]{.5f,1.5f,3,5.5f,7.5f})positions.Add(new Vector3(x,y,z));foreach(float x in new[]{-4f,-2,0,2,4})foreach(float z in new[]{-2f,0,2})foreach(float y in new[]{.4f,1.3f,2.2f})positions.Add(new Vector3(x,y,z));probes.probePositions=positions.ToArray();
   var main=root.GetComponentInChildren<ArenaSceneLighting>(true).mainLight;foreach(var light in root.GetComponentsInChildren<Light>(true))light.lightmapBakeType=(c.optimize?light==main:light.type==LightType.Directional)?LightmapBakeType.Mixed:LightmapBakeType.Baked;
   var settings=new LightingSettings{name="Monteverdi_"+c.caseName,bakedGI=true,realtimeGI=false};settings.lightmapper=LightingSettings.Lightmapper.ProgressiveGPU;settings.lightmapResolution=c.bakeResolution;settings.lightmapMaxSize=1024;settings.directionalityMode=LightmapsMode.NonDirectional;settings.mixedBakeMode=MixedLightingMode.IndirectOnly;settings.directSampleCount=32;settings.indirectSampleCount=128;settings.environmentSampleCount=128;settings.maxBounces=2;settings.ao=true;settings.aoMaxDistance=1.2f;string path=Lab+"/"+c.caseName+"_LightingSettings.asset";var prior=AssetDatabase.LoadAssetAtPath<LightingSettings>(path);if(prior){EditorUtility.CopySerialized(settings,prior);Object.DestroyImmediate(settings);settings=prior;}else AssetDatabase.CreateAsset(settings,path);Lightmapping.lightingSettings=settings;
  }
  EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),ScenePath(c));AssetDatabase.SaveAssets();
 }
 static void FinishBake(Cmd c){var root=Arena();foreach(var probe in root.GetComponentsInChildren<ReflectionProbe>(true)){probe.mode=ReflectionProbeMode.Baked;probe.resolution=128;string path=Lab+"/"+c.caseName+"_Reflection.exr";if(!Lightmapping.BakeReflectionProbe(probe,path))throw new Exception("Reflection bake failed");AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var cube=AssetDatabase.LoadAssetAtPath<Cubemap>(path);if(!cube)throw new Exception("No baked cubemap "+path);probe.mode=ReflectionProbeMode.Custom;probe.customBakedTexture=cube;}
  EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),ScenePath(c));AssetDatabase.SaveAssets();File.WriteAllText(Output+"/"+c.caseName+"_bake.txt","seconds="+bakeWatch.Elapsed.TotalSeconds+"\nlightmaps="+LightmapSettings.lightmaps.Length+"\nprobes="+(LightmapSettings.lightProbes?LightmapSettings.lightProbes.count:0));Write(new Reply{id=c.id,ok=true,path=ScenePath(c),seconds=bakeWatch.Elapsed.TotalSeconds});
