 static void DisableAdditional(UniversalRenderPipelineAsset pipeline){var serialized=new SerializedObject(pipeline);serialized.FindProperty("m_AdditionalLightsRenderingMode").intValue=0;serialized.ApplyModifiedPropertiesWithoutUndo();}
 static void SetQuality(Cmd c){oldQuality=QualitySettings.GetQualityLevel();QualitySettings.SetQualityLevel(Array.IndexOf(QualitySettings.names,c.quality),true);oldPipeline=QualitySettings.renderPipeline;oldVsync=QualitySettings.vSyncCount;var pipeline=Object.Instantiate((UniversalRenderPipelineAsset)oldPipeline);pipeline.name="Pilot temporary pipeline";pipeline.msaaSampleCount=c.msaa;pipeline.renderScale=c.scale;pipeline.supportsCameraOpaqueTexture=false;if(c.isolated)pipeline.volumeProfile=ScriptableObject.CreateInstance<VolumeProfile>();if(c.optimize){DisableAdditional(pipeline);pipeline.shadowDistance=25;pipeline.shadowCascadeCount=2;pipeline.mainLightShadowmapResolution=1024;}QualitySettings.renderPipeline=pipeline;QualitySettings.vSyncCount=0;}
 static void RestoreQuality(){foreach(var entry in textureState)if(entry.Key){entry.Key.filterMode=entry.Value.filter;entry.Key.anisoLevel=entry.Value.aniso;}textureState.Clear();if(oldPipeline){var temporary=QualitySettings.renderPipeline;QualitySettings.renderPipeline=oldPipeline;QualitySettings.vSyncCount=oldVsync;QualitySettings.SetQualityLevel(oldQuality,true);oldPipeline=null;if(temporary&&temporary.name=="Pilot temporary pipeline")Object.DestroyImmediate(temporary);}}
 static Camera CameraFor(Cmd c){var root=Arena();var cam=new GameObject("PilotCamera").AddComponent<Camera>();cam.fieldOfView=54;cam.nearClipPlane=.15f;cam.farClipPlane=180;cam.allowMSAA=c.msaa>1;cam.allowHDR=true;cam.aspect=(float)c.width/c.height;cam.transform.position=new Vector3(1.5f,2,-7);cam.transform.LookAt(new Vector3(-1,3.1f,6));if(c.view==1){cam.transform.position=new Vector3(4.5f,2.2f,-3.8f);cam.transform.LookAt(new Vector3(-4,3.2f,6));}if(c.view==2){cam.transform.position=new Vector3(0,2.8f,-4);cam.transform.LookAt(new Vector3(0,0,4));}
  if(c.composer=="Pachelbel"){var manifest=JsonUtility.FromJson<ComposerSceneryAssembly.Manifest>(File.ReadAllText("Assets/_Project/Configs/Editor/composer_scenery_manifest.json"));var spec=manifest.scenes.Single(s=>s.composer==c.composer);if(c.view==0&&spec.view!=null){cam.transform.position=spec.view.position;cam.transform.LookAt(spec.view.target);cam.fieldOfView=spec.view.fov;}}if(c.view==4){cam.transform.position=new Vector3(0,4.5f,-4.5f);cam.transform.LookAt(new Vector3(-2.8f,5.3f,6.5f));cam.fieldOfView=42;}var extra=cam.GetUniversalAdditionalCameraData();extra.renderPostProcessing=c.aa>0;if(c.isolated)extra.volumeLayerMask=0;extra.antialiasing=c.aa==1?AntialiasingMode.SubpixelMorphologicalAntiAliasing:c.aa==2?AntialiasingMode.FastApproximateAntialiasing:AntialiasingMode.None;extra.antialiasingQuality=AntialiasingQuality.High;var env=root.GetComponentInChildren<ArenaEnvironmentSettings>(true);env.Apply(root.GetComponentInChildren<ArenaSceneLighting>(true).mainLight,cam);if(c.view==3){cam.transform.position=new Vector3(1.5f,2,-7);cam.transform.LookAt(new Vector3(0,1.5f,0));var sampleMaterial=new Material(Shader.Find("Universal Render Pipeline/Lit"));sampleMaterial.SetColor("_BaseColor",new Color(.45f,.45f,.45f));sampleMaterial.SetFloat("_Smoothness",.25f);foreach(float x in new[]{-2.5f,2.5f}){var sample=GameObject.CreatePrimitive(PrimitiveType.Capsule);sample.name="ProbeTestCapsule";sample.transform.SetParent(root.transform,false);sample.transform.position=new Vector3(x,.9f,0);sample.transform.localScale=new Vector3(.55f,.9f,.55f);sample.GetComponent<Renderer>().sharedMaterial=sampleMaterial;sample.GetComponent<Renderer>().lightProbeUsage=LightProbeUsage.BlendProbes;}}if(c.stable)foreach(var texture in root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Where(m=>m).SelectMany(m=>m.GetTexturePropertyNames().Select(m.GetTexture)).OfType<Texture2D>().Distinct()){if(!textureState.ContainsKey(texture))textureState[texture]=(texture.filterMode,texture.anisoLevel);texture.filterMode=FilterMode.Trilinear;texture.anisoLevel=8;}return cam;
 }
 static Texture2D Render(Camera cam,Cmd c){var target=new RenderTexture(c.width,c.height,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB){antiAliasing=c.msaa};var resolved=new RenderTexture(c.width,c.height,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);var prior=RenderTexture.active;var tex=new Texture2D(c.width,c.height,TextureFormat.RGB24,false);try{target.Create();resolved.Create();cam.targetTexture=target;cam.Render();Graphics.Blit(target,resolved);RenderTexture.active=resolved;tex.ReadPixels(new Rect(0,0,c.width,c.height),0,0);tex.Apply();return tex;}finally{cam.targetTexture=null;RenderTexture.active=prior;target.Release();resolved.Release();Object.DestroyImmediate(target);Object.DestroyImmediate(resolved);}}
 static void BeginRender(Cmd c){Open(ScenePath(c));SetQuality(c);captureCamera=CameraFor(c);var small=new Cmd{width=64,height=36,msaa=c.msaa};var warm=Render(captureCamera,small);Object.DestroyImmediate(warm);pendingRender=c;readyAt=EditorApplication.timeSinceStartup+5;renderDeadline=EditorApplication.timeSinceStartup+45;EditorApplication.QueuePlayerLoopUpdate();}
 static void CaptureCase(Cmd c){Camera cam=captureCamera;captureCamera=null;try{for(int i=0;i<3;i++){var warm=Render(cam,c);Object.DestroyImmediate(warm);}var ms=new List<double>();Texture2D last=null;for(int i=0;i<Math.Max(c.frames,1);i++){if(last)Object.DestroyImmediate(last);var watch=Stopwatch.StartNew();last=Render(cam,c);watch.Stop();ms.Add(watch.Elapsed.TotalMilliseconds);}Directory.CreateDirectory(Output+"/captures");File.WriteAllBytes(Output+"/captures/"+c.caseName+"_"+c.width+"_v"+c.view+".png",last.EncodeToPNG());Object.DestroyImmediate(last);ms.Sort();var root=Arena();var record=new Capture{name=c.caseName,quality=c.quality,lighting=c.lighting,gpu=SystemInfo.graphicsDeviceName,graphicsApi=SystemInfo.graphicsDeviceType.ToString(),width=c.width,height=c.height,msaa=c.msaa,aa=c.aa,stable=c.stable,optimize=c.optimize,isolated=c.isolated,renderScale=c.scale,drawCalls=UnityStats.drawCalls,triangles=UnityStats.triangles,lightmaps=LightmapSettings.lightmaps.Length,lightProbes=LightmapSettings.lightProbes?LightmapSettings.lightProbes.count:0,realtimeLights=root.GetComponentsInChildren<Light>(true).Count(l=>l.enabled&&l.lightmapBakeType!=LightmapBakeType.Baked),reflectionProbes=root.GetComponentsInChildren<ReflectionProbe>(true).Length,medianRenderSyncMs=ms[ms.Count/2],minRenderSyncMs=ms.First(),maxRenderSyncMs=ms.Last(),lightmapBytes=LightmapSettings.lightmaps.Sum(l=>(double)(l.lightmapColor?UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(l.lightmapColor):0)),meshBytes=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh).Select(f=>f.sharedMesh).Distinct().Sum(m=>(double)UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(m))};File.WriteAllText(Output+"/captures/"+c.caseName+"_"+c.width+"_v"+c.view+".json",JsonUtility.ToJson(record,true));}finally{if(cam)Object.DestroyImmediate(cam.gameObject);RestoreQuality();}Write(new Reply{id=c.id,ok=true,path=Output+"/captures/"+c.caseName+"_"+c.width+"_v"+c.view+".png"});}
 static void VerifyPlay(){var root=Arena();var preview=Object.FindFirstObjectByType<MonteverdiLightingPreview>();if(!preview||QualitySettings.renderPipeline!=preview.pipeline)throw new Exception("Preview pipeline did not activate in Play Mode");if(!LightmapSettings.lightProbes||LightmapSettings.lightProbes.count==0)throw new Exception("No baked light probes in Play Mode");var floor=root.GetComponentsInChildren<MeshRenderer>(true).Single(r=>r.name=="Floor");if(floor.lightmapIndex<0||floor.lightmapIndex>=LightmapSettings.lightmaps.Length)throw new Exception("Floor lightmap binding lost in Play Mode");var probes=root.GetComponentsInChildren<ReflectionProbe>(true);if(probes.Any(p=>p.mode!=ReflectionProbeMode.Custom||!p.customBakedTexture))throw new Exception("Reflection cubemap missing in Play Mode");var report="PASS Play Mode\nlightmaps="+LightmapSettings.lightmaps.Length+"\nfloorLightmapIndex="+floor.lightmapIndex+"\nlightProbes="+LightmapSettings.lightProbes.count+"\nMSAA="+preview.pipeline.msaaSampleCount+"\nrenderScale="+preview.pipeline.renderScale+"\nrealtimeLights="+root.GetComponentsInChildren<Light>(true).Count(l=>l.enabled&&l.lightmapBakeType!=LightmapBakeType.Baked);File.WriteAllText(Output+"/"+playCommand.caseName+"_play.txt",report);var tex=Render(preview.GetComponent<Camera>(),playCommand);File.WriteAllBytes(Output+"/captures/"+playCommand.caseName+"_Play.png",tex.EncodeToPNG());Object.DestroyImmediate(tex);}
 static void FinalizeScene(Cmd c){Open(ScenePath(c));Directory.CreateDirectory(Lab+"/Profiles");var source=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/Quality/URP_"+c.quality+".asset");string profilePath=Lab+"/Profiles/"+c.caseName+".asset";var profile=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(profilePath);if(!profile){profile=Object.Instantiate(source);AssetDatabase.CreateAsset(profile,profilePath);}else EditorUtility.CopySerialized(source,profile);profile.msaaSampleCount=c.msaa;profile.renderScale=1;profile.supportsCameraOpaqueTexture=false;DisableAdditional(profile);profile.shadowDistance=25;profile.shadowCascadeCount=2;profile.mainLightShadowmapResolution=1024;var cam=CameraFor(c);cam.name="PreviewCamera_PressPlay";var setup=cam.gameObject.AddComponent<MonteverdiLightingPreview>();setup.pipeline=profile;setup.environment=Arena().GetComponentInChildren<ArenaEnvironmentSettings>(true);setup.sun=Arena().GetComponentInChildren<ArenaSceneLighting>(true).mainLight;RestoreQuality();EditorUtility.SetDirty(profile);EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),ScenePath(c));AssetDatabase.SaveAssets();}
 static void Motion(Cmd c){Camera cam=captureCamera;captureCamera=null;try{var start=cam.transform.position;Directory.CreateDirectory(Output+"/motion/"+c.caseName);for(int i=0;i<c.frames;i++){cam.transform.position=start+Vector3.right*(Mathf.Sin(i*Mathf.PI*2/c.frames)*.25f);var tex=Render(cam,c);File.WriteAllBytes(Output+"/motion/"+c.caseName+"/"+i.ToString("000")+".png",tex.EncodeToPNG());Object.DestroyImmediate(tex);}}finally{if(cam)Object.DestroyImmediate(cam.gameObject);RestoreQuality();}Write(new Reply{id=c.id,ok=true});}
}
